            'excerpt' => 'Appearance anniversary of Lord Hanuman, the supreme devotee of Sri Rama and embodiment of strength and selfless service.',
            'content_en' => 'Hanuman Jayanti commemorates the birth of Sri Hanuman, the son of Anjana and Kesari, blessed by Vayu Deva. In North India, it is observed on Chaitra Purnima. In Andhra Pradesh and Telangana, devotees observe 41 days of Hanuman Deeksha commencing on Chaitra Purnima and concluding with immense celebrations on Vaishakha Bahula Dashami (Telugu Hanuman Jayanti). Devotees offer Sindoor, recite Hanuman Chalisa 108 times, and perform Vadamaala archana.',
            'content_te' => 'శ్రీరామదాస భగవానుడైన ఆంజనేయ స్వామి జన్మదినాన్ని చైత్ర పౌర్ణమి నాడు మరియు తెలుగు రాష్ట్రాల్లో వైశాఖ బహుళ దశమి నాడు మహా ఘనంగా జరుపుకుంటారు. తెలుగునాట భక్తులు 41 రోజుల పాటు హనుమాన్ మండల దీక్ష ధరించి, జయంతి నాడు దీక్ష విరమిస్తారు. ఆకు పూజ (తమలపాకుల పూజ), సింధూర లేపనం, వడమాల సమర్పణ విశేషంగా చేస్తారు.',
            'content_hi' => 'हनुमान जयंती चैत्र पूर्णिमा को रामदूत संकटमोचन पवनपुत्र हनुमान जी के प्राकट्य उत्सव के रूप में मनाई जाती है। इस दिन सिंदूर अर्पण, चोला चढ़ाना और सुंदरकांड व हनुमान चालीसा का पाठ करने से सभी संकट दूर होते हैं।',
            'significance' => 'Unconditional devotion, moral rectitude, fearlessness, and victory over malefic planetary afflictions.',
            'history' => 'Born through the blessings of Lord Shiva and Vayu Deva to assist Lord Rama in vanquishing Ravana and establishing Dharma.',
            'puja_timings' => 'Morning Abhishekam: 06:00 AM – 10:30 AM | Evening Deeparadhana: 06:00 PM – 08:30 PM',
            'samagri' => 'Pure orange Sindoor, Jasmine oil (Chameli taila), 108 Betel leaves (Tamalapakulu) for garland, Red hibiscus flowers, Janeu, Tulasi garland',
            'naivedyam' => 'Vadas made of black gram (Vadamaala), Boondi Laddus, Jaggery, Bananas, Chana (soaked gram)',
            'vrat_rules' => 'Observance of strict celibacy (Brahmacharya), satvik diet, and recitation of Chalisa throughout the day.',
            'dos' => 'Chant Hanuman Chalisa 11 or 108 times, offer betel leaf garland, apply sindoor on forehead as prasad, feed monkeys or poor persons.',
            'donts' => 'Do not offer stale flowers, avoid non-vegetarian food, alcohol, and negative conduct.',
