            'content_en' => 'Akshaya Tritiya, also known as Akha Teej, is one of the most auspicious days in the Vedic calendar. The word Akshaya signifies that which never diminishes. Any noble deed, charity (Dana), japa, or investment started on this day multiplies perpetually. It marks the day Treta Yuga commenced, River Ganga descended to earth, Sage Vedavyasa began composing the Mahabharata with Lord Ganesha, and Sudama visited Lord Krishna and was blessed with limitless prosperity.',
            'content_te' => 'వైశాఖ శుద్ధ తృతీయ నాడు జరుపుకునే అక్షయ తృతీయ అత్యంత పవిత్రమైన స్వయంసిద్ధ ముహూర్త దినం. ఈ రోజున చేసిన దానం, జపం, పుణ్యకార్యాలు అక్షయమై తరగని పుణ్యఫలాన్ని ఇస్తాయి. గంగావతరణం, పరశురామ జయంతి ఈనాడే జరిగాయి. లక్ష్మీ-కుబేర పూజలు నిర్వహించి, బంగారు ఆభరణాలు లేదా కొత్త వస్తువులు కొనుగోలు చేయడం శుభప్రదం.',
            'content_hi' => 'वैशाख शुक्ल तृतीया को अक्षय तृतीया कहा जाता है। इस दिन किया गया दान, जप और सत्कर्म कभी क्षय नहीं होता। इसे अबूझ मुहूर्त माना जाता है जिसमें बिना पंचांग देखे कोई भी शुभ कार्य आरंभ किया जा सकता है।',
            'significance' => 'Inexhaustible prosperity (Akshaya), virtue, and spiritual abundance through noble charity.',
