            'content_en' => 'Narasimha Jayanti marks the appearance of the fierce yet deeply protective half-man, half-lion incarnation of Lord Vishnu. Lord Narasimha manifested from a stone pillar at dusk (Sandhya kala) on Vaishakha Shukla Chaturdashi to vanquish the tyrant demon king Hiranyakashipu and vindicate the pure unshakeable devotion of child Prahlada.',
            'content_te' => 'వైశాఖ శుద్ధ చతుర్దశి సాయంసంధ్యా కాలంలో స్వామివారు స్తంభోద్భవుడై హిరణ్యకశిపుని సంహరించి భక్త ప్రహ్లాదుని రక్షించారు. సింహాచలం, యాదగిరిగుట్ట, మంగళగిరి, అహోబిలం వంటి ప్రసిద్ధ నరసింహ క్షేత్రాలలో జయంతి ఉత్సవాలు అత్యంత వైభవంగా జరుగుతాయి.',
            'content_hi' => 'वैशाख शुक्ल चतुर्दशी को गोधूलि वेला में भक्त प्रह्लाद की रक्षा के लिए भगवान नृसिंह खंभे को चीरकर प्रकट हुए थे। इस दिन सायं काल की पूजा से सभी प्रकार के भय और संकटों का निवारण होता है।',
            'significance' => 'God is omnipresent and will manifest instantly to protect sincere devotees from adversity.',
