            'excerpt' => 'Tribute to spiritual preceptors and birthday of Sage Krishna Dvaipayana Veda Vyasa, the compiler of the Vedas.',
            'content_en' => 'Guru Purnima is dedicated to honoring the spiritual teacher (Guru) who dispels the darkness of ignorance (Gu) with the illuminating light of knowledge (Ru). It is also celebrated as Vyasa Purnima, marking the appearance anniversary of Sage Veda Vyasa, who classified the single Veda into four, composed the 18 Puranas, the Mahabharata, and the Brahma Sutras. Seekers and sannyasis commence their 4-month Chaturmasya vrata on this day.',
            'content_te' => 'ఆషాఢ శుద్ధ పౌర్ణమి నాడు వ్యాస భగవానుని జన్మదినాన్ని గురు పౌర్ణమిగా జరుపుకుంటారు. అజ్ఞానాంధకారాన్ని పోగొట్టి జ్ఞానజ్యోతిని వెలిగించే గురువులను ఈ రోజున పూజించి పాదాభివందనం చేస్తారు. సన్యాసులు ఈ రోజు నుంచే చాతుర్మాస్య వ్రతాన్ని ప్రారంభిస్తారు.',
            'content_hi' => 'आषाढ़ मास की पूर्णिमा को गुरु पूर्णिमा कहा जाता है। इस दिन महर्षि वेदव्यास जी का जन्म हुआ था। यह दिन जीवन में गुरु के प्रति कृतज्ञता व्यक्त करने और उनका आशीर्वाद प्राप्त करने का महापर्व है।',
            'significance' => 'Reverence to spiritual preceptors, gratitude for divine knowledge, and inception of sacred Chaturmasya.',
            'history' => 'Sage Vyasa was born on this day to Sage Parashara and Satyavati; Lord Shiva became the Adi Guru (Dakshinamurthy) imparting wisdom to Saptarshis.',
