            'excerpt' => 'Tholi Ekadashi in Telugu tradition and Devshayani Ekadashi, when Lord Vishnu enters yoga nidra for four months.',
            'content_en' => 'Ashadha Shukla Ekadashi is celebrated as "Tholi Ekadashi" (the first and most important Ekadashi) in Telangana and Andhra Pradesh. In Maharashtra, millions of Warkaris complete their holy Palkhi pilgrimage to Pandharpur. From this day, Lord Vishnu enters mystic slumber (Yoga Nidra) in the cosmic ocean of milk for four months, initiating the holy Chaturmasya period during which auspicious wedding ceremonies are paused.',
            'content_te' => 'తెలుగువారికి తొలి ఏకాదశి అత్యంత పవిత్రమైన ఉపవాస దినం. ఈ రోజు నుంచి శ్రీమహావిష్ణువు క్షీరసాగరంలో శేషతల్పంపై యోగనిద్రలోకి ప్రవేశిస్తారు. అందుకే దీనిని శయనీ ఏకాదశి అంటారు. భక్తులు రోజంతా ఉపవాసం ఉండి, రాత్రి జాగరణ చేసి మరుసటి రోజు ద్వాదశి పారణ చేస్తారు.',
            'content_hi' => 'आषाढ़ शुक्ल एकादशी को देवशयनी या हरिशयनी एकादशी कहा जाता है। इस दिन से भगवान विष्णु चार मास के लिए योगनिद्रा में चले जाते हैं और चातुर्मास आरंभ होता है। महाराष्ट्र में पंढरपुर वारी यात्रा इसी दिन पूर्ण होती है।',
            'significance' => 'Detoxification of body, spiritual contemplation, and devotion to Lord Vishnu through strict Ekadashi fasting.',
            'history' => 'Described in the Bhavishyottara Purana; Lord Krishna explained the glory of this vrata to King Yudhishthira.',
