            'content_te' => 'శ్రావణ శుద్ధ పంచమి నాడు నాగ పంచమి లేదా గరుడ పంచమి జరుపుకుంటారు. మహిళలు ఉదయాన్నే స్నానం చేసి పాముల పుట్టల వద్దకు వెళ్లి పాలు, గుడ్లు, పసుపు, కుంకుమ సమర్పిస్తారు. అన్నదమ్ముల ఆయురారోగ్యాల కోసం, కాలసర్ప దోష నివారణ కోసం నాగ పూజ చేస్తారు.',
            'content_hi' => 'श्रावण शुक्ल पंचमी को नाग पंचमी मनाई जाती है। इस दिन नाग देवताओं को दूध अर्पित करने से कालसर्प दोष और सर्प भय से मुक्ति मिलती है।',
