            'excerpt' => 'State festival of Telangana offering decorated pots of rice and jaggery (Bhojanam) to Mother Mahakali for protection.',
            'content_en' => 'Bonalu is the iconic state festival of Telangana celebrated during Ashadha Masam. The word Bonam is derived from "Bhojanam" (meal). Women dress in traditional silk sarees and carry earthen pots decorated with turmeric, kumkum, and neem leaves atop their heads, containing rice cooked with milk and jaggery, topped with a lighted lamp. The festival travels across Golconda Jagadambika temple, Secunderabad Ujjaini Mahakali, and Old City Lal Darwaza, accompanied by Pothuraju dances and Rangam prophecy.',
            'content_te' => 'తెలంగాణ సంస్కృతికి ప్రతీక అయిన బోనాల పండుగ ఆషాఢ మాసంలో ఘనంగా జరుగుతుంది. అమ్మవారికి సమర్పించే నైవేద్యాన్నే "బోనం" (భోజనం) అంటారు. మహిళలు పసుపు, కుంకుమ, వేప ఆకులతో అలంకరించిన కుండలలో పాలు, బెల్లంతో వండిన అన్నంపై దీపం వెలిగించి నెత్తిన పెట్టుకుని ఊరేగింపుగా ఆలయాలకు వెళ్లి సమర్పిస్తారు. పోతురాజుల విన్యాసాలు, రంగం భవిష్యవాణి ప్రత్యేక ఆకర్షణ.',
            'content_hi' => 'बोनालु तेलंगाना का राज्य पर्व है जो आषाढ़ मास में महाकाली के सम्मान में मनाया जाता है। महिलाएं सिर पर हल्दी, कुमकुम और नीम से सजी मटकियों में प्रसाद (भात और गुड़) लेकर मंदिर जाती हैं।',
            'significance' => 'Thanksgiving to Mother Goddess for protecting the city from pestilence and blessing the community with health.',
            'history' => 'Originated in 1813 during the twin cities plague outbreak when military personnel prayed to Ujjaini Mahakali and established shrines.',
            'puja_timings' => 'Bonam Samarpan: Full Day Sundays during Ashadha Masam',
