            'vrat_rules' => 'Traditional fast until the Bonam pot is presented to the deity.',
            'dos' => 'Adorn pots with neem leaves and burning ghee lamps, welcome the Mother Goddess as a daughter returning home.',
            'donts' => 'Avoid disrespecting folk traditions, handle the sacred Bonam with reverence and hygiene.',
