            'excerpt' => 'Sacred Friday vrata performed by married women invoking Ashta Lakshmi for marital bliss, health, and family abundance.',
            'content_en' => 'Varalakshmi Vratam is observed on the Friday preceding Shravana Purnima. Worshipping Goddess Varalakshmi is equivalent to worshipping all eight forms of Lakshmi (Ashta Lakshmi). The observance features Kalasha Sthapana adorned with a coconut and goddess face (Ammavari mukham), tying the sacred nine-knot yellow thread (Toram) around the right wrist, and distributing auspicious Vayanam (blouse piece, fruits, betel leaves, and bangles) to married women (Muttaiduvulu).',
            'content_te' => 'శ్రావణ పౌర్ణమికి ముందు వచ్చే శుక్రవారం నాడు ముత్తైదువలు వరలక్ష్మీ వ్రతాన్ని ఆచరిస్తారు. కలశాన్ని అమ్మవారిగా అలంకరించి, తొమ్మిది ముడుల తోరాలను పూజించి కుడిచేతికి కట్టుకుంటారు. తొమ్మిది రకాల పిండివంటలు నైవేద్యంగా పెట్టి, తోటి ముత్తైదువలకు వాయనాలు అందిస్తారు. ఇది సకల సౌభాగ్యాలను ప్రసాదించే మహావ్రతం.',
            'content_hi' => 'श्रावण मास की पूर्णिमा से पहले आने वाले शुक्रवार को वरलक्ष्मी व्रत रखा जाता है। इसमें अष्टलक्ष्मी के स्वरूप में माता लक्ष्मी की पूजा की जाती है और सौभाग्यवती महिलाएं परिवार की सुख-समृद्धि हेतु यह व्रत करती हैं।',
            'significance' => 'Marital longevity, harmony, relief from debts, and attainment of the eight-fold boons of Ashta Lakshmi.',
            'history' => 'Revealed by Lord Shiva to Goddess Parvati, chronicled through the story of the virtuous devotee Charumati in the Skanda Purana.',
