            'excerpt' => 'Sacred festival celebrating the bond of protection and affection between brothers and sisters, and Vedic Upakarma.',
            'content_en' => 'Raksha Bandhan celebrates the sacred bond of love and mutual protection between sisters and brothers. Sisters tie the auspicious Rakhi thread around their brother\'s right wrist, apply tilak, perform aarti, and pray for his prosperity and long life, while brothers offer gifts and pledge lifetime protection. In South India, Shravana Purnima is also observed as "Jandhyala Purnima" (Upakarma) where Brahmins change their sacred thread (Yajnopavita).',
            'content_te' => 'శ్రావణ పౌర్ణమి నాడు రక్షాబంధన్ మరియు జంధ్యాల పౌర్ణమి (ఉపాకర్మ) నిర్వహించుకుంటారు. సోదరీమణులు తమ సోదరుల క్షేమాన్ని కాంక్షిస్తూ కుడిచేతికి రాఖీ కట్టి, తిలకం దిద్ది, మిఠాయిలు తినిపిస్తారు. బ్రాహ్మణులు నూతన యజ్ఞోపవీతాన్ని ధరించి పూర్వ ఋషులకు తర్పణాలు సమర్పిస్తారు.',
            'content_hi' => 'श्रावण पूर्णिमा को भाई-बहन के अटूट प्रेम का प्रतीक रक्षाबंधन मनाया जाता है। बहनें भाइयों की कलाई पर रक्षासूत्र बांधती हैं और भाई उनकी रक्षा का वचन देते हैं। भद्रा काल में राखी बांधना वर्जित माना जाता है।',
            'significance' => 'Fraternal protection, selfless love, family cohesion, and spiritual renewal through Upakarma.',
            'history' => 'Draupadi tied a strip of her saree around Sri Krishna\'s bleeding finger; Indrani tied sacred thread to Indra before defeating asuras.',
