            'excerpt' => 'Midnight birth anniversary of Lord Sri Krishna, the eighth avatar of Vishnu, with butter offerings and Dahi Handi.',
            'content_en' => 'Krishna Janmashtami celebrates the descent of the Supreme Lord Sri Krishna in Mathura prison to Devaki and Vasudeva at midnight during Rohini Nakshatra. Devotees observe strict waterless or fruit fast throughout the day, decorate home entrances with baby Krishna\'s footprints (Chinni Krishna Paadalu) drawn with rice flour, perform midnight abhishekam with panchamritam, offer fresh homemade white butter (Vennamudda), and celebrate the joyous breaking of buttermilk pots (Utlotsavam / Dahi Handi).',
            'content_te' => 'శ్రావణ బహుళ అష్టమి రోహిణీ నక్షత్ర అర్ధరాత్రి వేళ శ్రీకృష్ణ పరమాత్మ జన్మించారు. గృహాలలో చిన్ని కృష్ణుని పాదాల ముగ్గులు వేసి స్వామిని ఆహ్వానిస్తారు. రోజంతా ఉపవాసం ఉండి, అర్ధరాత్రి వేళ కృష్ణునికి పంచామృత స్నానం చేయించి, వెన్నముద్దలు, అటుకులు, పండ్లను నైవేద్యంగా సమర్పిస్తారు. మరుసటి రోజు ఉట్లోత్సవం ఉత్సాహంగా నిర్వహిస్తారు.',
            'content_hi' => 'भाद्रपद कृष्ण अष्टमी की आधी रात को रोहिणी नक्षत्र में भगवान श्रीकृष्ण का जन्म हुआ था। भक्त दिनभर उपवास रखकर मध्यरात्रि में कान्हा का जन्मोत्सव मनाते हैं, माखन-मिश्री का भोग लगाते हैं और दही हांडी उत्सव मनाते हैं।',
            'significance' => 'Establishment of Dharma, surrender (Sharanagati), divine joy, and Bhagavad Gita\'s message of selfless action.',
            'history' => 'Described in the Tenth Canto of Srimad Bhagavatam.',
            'puja_timings' => 'Nishita Kala Midnight Janmotsav: 11:45 PM – 12:40 AM',
            'samagri' => 'Idol of Bal Gopal in a cradle (Uyyala), Panchamritam, Tulasi leaves, Peacock feathers (Nemali pincha), Butter, Flute, Yellow cloth',
            'naivedyam' => 'Fresh unsalted white butter (Vennamudda), Poha with jaggery (Atukulu), Murukulu, Laddus, Seedai, Fruits',
            'vrat_rules' => 'Fasting until midnight Nishita puja; break fast with panchamrita prasad after midnight archana.',
            'dos' => 'Draw baby Krishna footprints into the house, rock the swing cradle, chant Hare Krishna Mahamantra and Bhagavad Gita verses.',
            'donts' => 'Do not break fast before midnight; avoid tamasic food.',
