            'excerpt' => 'Grand festival celebrating the birth of Lord Ganesha with clay idol sthapana, 21 patri archana, and Modaka offerings.',
            'content_en' => 'Ganesh Chaturthi (Vinayaka Chavithi) celebrates the appearance of Lord Ganesha, the elephant-headed son of Shiva and Parvati, the remover of all obstacles and harbinger of wisdom. Devotees install eco-friendly clay idols (Matti Vinayakudu) at home and in public pandals during Madhyahna muhurat. The puja features sacred 21-leaf archana (Eka-Vimshati Patri Puja), reciting the Vinayaka Vratha Katha, offering steamed Kudumulu and Modakas, and chanting the Ganesha Atharvashirsha.',
            'content_te' => 'భాద్రపద శుద్ధ చవితి మధ్యాహ్న వేళ విఘ్నేశ్వరుడు ఆవిర్భవించిన పవిత్ర దినం. పర్యావరణహిత మట్టి గణపతులను ప్రతిష్టించి, 21 రకాల పవిత్ర పత్రాలతో (ఏకవింశతి పత్రి పూజ) పూజిస్తారు. వినాయక వ్రత కథను పఠించి, అక్షతలు తలపై వేసుకుంటారు. కుడుములు, ఉండ్రాళ్ళు నైవేద్యంగా సమర్పిస్తారు. చంద్రదర్శన దోష నివారణకు శ్యమంతకోపాఖ్యానం వినడం సంప్రదాయం.',
            'content_hi' => 'भाद्रपद शुक्ल चतुर्थी को विघ्नहर्ता भगवान श्री गणेश का प्राकट्य दिवस मनाया जाता है। दोपहर में गणेश जी की मिट्टी की प्रतिमा स्थापित कर 21 प्रकार के पत्रों और मोदक से पूजन किया जाता है। इस दिन चंद्र दर्शन निषेध माना जाता है।',
            'significance' => 'Prathama Puja (first worship) for obstacle removal, wisdom, intellectual clarity, and auspicious beginnings.',
            'history' => 'Goddess Parvati fashioned Ganesha from turmeric paste; Sage Vedavyasa commenced dictating the Mahabharata to Ganesha on this day.',
            'puja_timings' => 'Madhyahna Ganesha Sthapana Muhurat: 11:05 AM – 01:35 PM | Avoid Moon Sighting: 09:15 AM – 08:45 PM',
            'samagri' => 'Eco-friendly Clay Ganesha, 21 Sacred leaves (Patri: Macheepatri, Bruhati, Bilva, Durva, Datura, Badari, etc.), Red flowers, Turmeric (for Haridra Ganapati), Kumkum, Janeu, Betel nuts, Coconut',
            'naivedyam' => 'Steamed rice dumplings (Undrallu / Kudumulu), Jaggery Modakas, Chalimidi, Vadapappu, Poha, Guava, Bananas',
            'vrat_rules' => 'Avoid looking at the moon to prevent Mithya Kalanka (false accusations); recite Syamantaka Mani katha.',
