            'excerpt' => 'Solemn and celebratory immersion of Lord Ganesha idols in water bodies culminating the ten-day Ganeshotsav.',
            'content_en' => 'Ganesh Visarjan marks the concluding rite of Ganeshotsav on Ananta Chaturdashi. After 10 days of loving hospitality, devotees bid farewell to Lord Ganesha, praying that He return early next year ("Ganapati Bappa Morya, Pudhchya Varshi Laukariya"). The clay idol dissolves into water, symbolizing the cosmic cycle of form returning to the formless form (Nirakara). In Hyderabad, the massive Hussain Sagar Shobhayatra is renowned worldwide.',
            'content_te' => 'అనంత చతుర్దశి నాడు వినాయక నవరాత్రులు ముగుస్తాయి. భక్తులు స్వామివారికి వీడ్కోలు పలుకుతూ శోభాయాత్రగా జలాశయాలకు తరలించి నిమజ్జనం చేస్తారు. మట్టితో చేసిన రూపం మళ్లీ నీటిలో లీనమై ప్రకృతిలో కలవడం ఆత్మ-పరమాత్మల ఐక్యతను తెలియజేస్తుంది. హైదరాబాద్ హుస్సేన్ సాగర్ నిమజ్జనం జగద్విఖ్యాతం.',
            'content_hi' => 'अनंत चतुर्दशी को 10 दिवसीय गणेशोत्सव का समापन होता है। भक्त गाजे-बाजे के साथ बप्पा को विदाई देते हैं और जल में प्रतिमा का विसर्जन करते हैं। यह निराकार से साकार और पुनः निराकार में विलीन होने का प्रतीक है।',
            'significance' => 'Detachment, impermanence, and the philosophical truth that all physical forms dissolve back into cosmic energy.',
            'history' => 'Sage Vyasa dictated the Mahabharata over 10 days; on the 10th day, Ganesha bathed in the river to cool his immense body heat.',
            'puja_timings' => 'Morning Visarjan: 06:15 AM – 10:45 AM | Afternoon: 01:15 PM – 04:30 PM',
            'samagri' => 'Curd rice, Flowers, Vermilion, Camphor, Coconut for breaking, Modakas',
            'naivedyam' => 'Daddojanam (Curd rice), Pulihora, Modakas for the journey',
            'vrat_rules' => 'Perform Uttarpuja (closing worship) with aarti before lifting the idol from its seat.',
            'dos' => 'Immerse clay idols in clean natural water or household immersion buckets; chant Ganesha mantras during transit.',
            'donts' => 'Do not disrespect the idol during transit; avoid polluting water bodies with non-biodegradable decorations.',
