            'excerpt' => 'Nine sacred nights invoking Goddess Durga in Her nine divine forms culminating in Vijayadashami.',
            'content_en' => 'Sharad Navratri is celebrated during the autumn month of Ashwina. Dedicated to Mother Durga, the nine nights honour the nine manifestations (Navadurga: Shailaputri, Brahmacharini, Chandraghanta, Kushmanda, Skandamata, Katyayani, Kalaratri, Mahagauri, and Siddhidatri). In Telugu states, Goddess Kanaka Durga at Vijayawada Indrakeeladri is decorated in ten different alankarams (including Balatripurasundari, Annapurna, Saraswati on Moola Nakshatra, and Mahishasuramardini). Devotees observe Ghatasthapana, fast, and recite Chandi Saptashati.',
            'content_te' => 'ఆశ్వయుజ శుద్ధ పాడ్యమి నుంచి తొమ్మిది రోజుల పాటు దేవీ నవరాత్రులు అత్యంత వైభవంగా జరుగుతాయి. విజయవాడ ఇంద్రకీలాద్రిపై కనకదుర్గమ్మ వారు రోజుకో దివ్య అలంకారంలో భక్తులకు దర్శనమిస్తారు. మూలా నక్షత్రం నాడు సరస్వతీ దేవిగా, దుర్గాష్టమి నాడు దుర్గాదేవిగా పూజలందుకుంటారు. ఘటస్థాపన చేసి చండీ సప్తశతీ పారాయణ, కుంకుమార్చనలు చేస్తారు.',
            'content_hi' => 'आश्विन मास के शुक्ल पक्ष की प्रतिपदा से शारदीय नवरात्रि आरंभ होती है। नौ दिनों तक मां दुर्गा के नौ रूपों की उपासना की जाती है। घटस्थापना, अखंड ज्योति और दुर्गा सप्तशती पाठ का विशेष महत्व है।',
            'significance' => 'Triumph of divine consciousness (Shakti) over demonic tendencies (ego, lust, greed) and spiritual rejuvenation.',
            'history' => 'Goddess Durga fought the buffalo demon Mahishasura for nine nights and vanquished him on the tenth day.',
            'puja_timings' => 'Ghatasthapana Muhurat: 06:15 AM – 08:35 AM | Abhijit Muhurat: 11:45 AM – 12:35 PM',
            'samagri' => 'Kalasham, Nine grains (Navadhanya), Red cloth, Mango leaves, Coconut, Red hibiscus, Kumkum, Akshata, Akhanda Deepam lamp',
            'naivedyam' => 'Ksheerannam (Payasam), Sweet Pongal, Vadapappu, Chalimidi, Sundal, Pulihora',
            'vrat_rules' => 'Strict satvik or fruit diet, morning and evening Sandhya aarti, maintaining Akhanda Deepam without letting it extinguish.',
            'dos' => 'Perform Ghatasthapana during shubh muhurat, recite Durga Saptashati, worship young girls (Kanya Puja), perform Kumkumarchana.',
            'donts' => 'Do not cut hair, nails, or shave during Navratri; strictly avoid tamasic food and anger.',
