            'seo_desc_te' => 'శరన్నవరాత్రుల ఘటస్థాపన ముహూర్తం, ఇంద్రకీలాద్రి దేవీ అలంకారాల జాబితా, కుంకుమార్చన విధానం ధర్మ జ్యోతి వేదికలో చదవండి.',
