            'excerpt' => 'Triumph of Good over Evil, Ayudha Puja, Shami Puja, exchange of Jammi leaves, and commencement of new ventures.',
            'content_en' => 'Vijayadashami (Dussehra / Dasara) culminates Navratri celebrating the victory of Mother Durga over Mahishasura and Lord Rama\'s victory over Ravana. In Telugu culture, people perform Ayudha Puja for tools, books, and vehicles, visit Shami (Jammi) trees in the evening, recite the sacred Shami prayer, exchange Jammi leaves with elders as gold (Bangaram), and seek blessings. It is an unmatched auspicious day for beginning studies (Vidyarambham) or launching new enterprises.',
            'content_te' => 'ఆశ్వయుజ శుద్ధ దశమి నాడే విజయదశమి. దుష్టరాక్షసుడైన మహిషాసురుని దుర్గాదేవి సంహరించిన రోజు, రావణాసురునిపై శ్రీరాముడు విజయం సాధించిన రోజు. సాయంత్రం జమ్మి చెట్టు (శమీ వృక్షం) వద్దకు వెళ్లి పూజ చేసి, జమ్మి ఆకులను "బంగారం"గా భావించి పెద్దల చేతుల్లో పెట్టి ఆశీర్వాదం తీసుకుంటారు. వాహన పూజ, ఆయుధ పూజ, విద్యారంభం ఈనాటి ముఖ్య విశేషాలు.',
            'content_hi' => 'विजयादशमी पर भगवान राम ने रावण का वध कर धर्म की पुनर्स्थापना की थी और मां दुर्गा ने महिषासुर का संहार किया था। इस दिन शमी वृक्ष का पूजन और शस्त्र पूजन किया जाता है। किसी भी नए कार्य की शुरुआत के लिए यह दिन सर्वोत्तम है।',
            'significance' => 'Total triumph of Dharma over Adharma, victory in all undertakings, and auspicious start of learning.',
            'history' => 'The Pandavas retrieved their concealed celestial weapons from the Shami tree after completing their year in incognito (Agyatavasa).',
            'puja_timings' => 'Aparahna Vijay Muhurat: 01:50 PM – 02:40 PM | Shami Puja: 05:15 PM – 06:45 PM',
            'samagri' => 'Shami tree leaves (Jammi aaku), Turmeric, Kumkum, Books, Work tools, Vehicle garland, Sweets, Betel leaves',
            'naivedyam' => 'Boorelu, Garelu, Paramannam, Sweet Pongal',
            'vrat_rules' => 'Perform Shami puja during twilight and seek blessings by sharing Jammi leaves with family.',
            'dos' => 'Recite "Shami Shamayate Papam", touch elders\' feet with Jammi leaves, launch new education or businesses.',
            'donts' => 'Do not harm trees or conduct egoistic quarrels on this day of divine victory.',
