            'title_en' => 'Diwali (Deepavali & Lakshmi Puja)',
            'title_te' => 'దీపావళి (లక్ష్మీ కుబేర పూజ & దీపోత్సవం)',
            'title_hi' => 'दीपावली (लक्ष्मी-कुबेर पूजन)',
