),
            'excerpt' => 'The universal Festival of Lights celebrating the illumination of knowledge over darkness, and Sri Maha Lakshmi Puja.',
            'content_en' => 'Deepavali (Diwali), the festival of lights, occurs on the darkest night of the year (Ashwina Amavasya). Devotees illuminate homes with rows of clay lamps (Diyas) using cow ghee or sesame oil to welcome Goddess Mahalakshmi and Lord Kubera. The evening Pradosha period is dedicated to Lakshmi-Kubera Puja for family prosperity, freedom from debts, and spiritual enlightenment. In North India, it celebrates Lord Rama\'s return to Ayodhya; in South India, the morning begins with Naraka Chaturdashi oil bath celebrating the victory of Satyabhama and Krishna over Narakasura.',
            'content_te' => 'చీకటిని పారద్రోలి వెలుగులు నింపే పవిత్ర పండుగ దీపావళి. ఆశ్వయుజ అమావాస్య సాయంకాలం ప్రదోష వేళలో శ్రీ మహాలక్ష్మి, వినాయకుడు మరియు కుబేరునికి శాస్త్రోక్తంగా పూజలు నిర్వహిస్తారు. ఇంటింటా మట్టి ప్రమిదలలో ఆవునెయ్యి లేదా నువ్వుల నూనెతో దీపాలు వెలిగిస్తారు. వ్యాపారస్తులు నూతన లెక్కల పుస్తకాలను (చోప్డా పూజ) ప్రారంభిస్తారు.',
            'content_hi' => 'दीपावली अंधकार पर प्रकाश और अधर्म पर धर्म की विजय का महापर्व है। इस दिन प्रदोष काल में मां लक्ष्मी और भगवान गणेश का षोडशोपचार पूजन किया जाता है। घर-घर में मिट्टी के दीप जलाए जाते हैं और सुख-समृद्धि की कामना की जाती है।',
            'significance' => 'Awakening the light of inner consciousness, welcoming virtuous wealth (Lakshmi), and dissipating ignorance.',
            'history' => 'Mother Lakshmi emerged during the churning of the cosmic ocean (Samudra Manthan) on this tithi; Sri Rama returned to Ayodhya.',
            'puja_timings' => 'Lakshmi Puja Pradosha Muhurat: 06:45 PM – 08:35 PM | Nishita Kala: 11:40 PM – 12:30 AM',
            'samagri' => 'Clay diyas, Pure cow ghee / sesame oil, Lotus flowers, Silver/gold coin, Betel leaves, Panchamritam, Kheel-Batasha (puffed rice and sugar candies), Red silk cloth',
            'naivedyam' => 'Laddus, Kaju Katli, Ksheerannam, Poha with jaggery, Seasonal fruits',
            'vrat_rules' => 'Cleanse homes thoroughly, maintain inner purity, light lamps before twilight, perform Lakshmi archana.',
            'dos' => 'Light minimum 21 or 108 clay lamps, perform Lakshmi-Kubera puja during Pradosha lagna, chant Sri Sukta and Lakshmi mantras.',
            'donts' => 'Do not leave home in darkness; avoid gambling, alcohol, or creating excessive smoke.',
