            'excerpt' => 'Tripurari Purnima celebrated with 365-wick deeparadhana under Usiri (Amla) tree, Satyanarayana Vratham, and Shiva temple darshan.',
            'content_en' => 'Karthika Purnima, also hailed as Tripurari Purnima or Deva Deepavali, is the pinnacle of the holy Karthika Masam. Lord Shiva destroyed the three demonic cities of Tripura Asuras on this day. Devotees take early morning river baths (Nadi Snana), perform Satyanarayana Swamy Vratham, and light 365 cotton wicks soaked in pure cow ghee (representing all 365 days of the year) on raw rice or halved raw amla fruits (Usiri Deepam) in Shiva temples at twilight.',
            'content_te' => 'కార్తీక పౌర్ణమి కార్తీక మాసంలో అత్యంత మహిమాన్వితమైన రోజు. శివకేశవులకు అత్యంత ప్రీతిపాత్రమైన ఈ రోజున తెల్లవారుజామున నదీస్నానం చేసి, సాయంకాలం శివాలయాలలో 365 వత్తులతో నెయ్యి దీపాలు వెలిగిస్తారు. ఉసిరి చెట్టు కింద ఉసిరికాయలపై దీపాలు పెట్టడం (ఉసిరి దీపోత్సవం), సత్యనారాయణ వ్రతం ఆచరించడం జన్మజన్మల పాపాలను హరిస్తుంది.',
            'content_hi' => 'कार्तिक पूर्णिमा को त्रिपुरारी पूर्णिमा और देव दीपावली कहा जाता है। इस दिन भगवान शिव ने त्रिपुरासुर का वध किया था। इस पावन तिथि पर गंगा स्नान और 365 बत्तियों का दीपदान करने से मोक्ष की प्राप्ति होती है।',
            'significance' => 'Dissolution of accumulated sins, harmony of Shiva and Vishnu (Hari-Hara), and attainment of Shiva Sayujya.',
            'history' => 'Lord Shiva destroyed the three iron, silver, and gold flying cities of Tarakaksha, Kamalaksha, and Vidyunmali with a single cosmic arrow.',
