            'excerpt' => 'Three-day grand harvest festival marking Uttarayana Punya Kala: Bhogi Mantalu, Sankranti Pongal, and Kanuma Pasuvula Puja.',
            'content_en' => 'Makara Sankranti celebrates the auspicious celestial ingress of the Sun (Surya) into Makara Rashi (Capricorn), commencing the auspicious six-month northern movement (Uttarayana). In Andhra Pradesh and Telangana, it is celebrated as the grand three-day "Pedda Panduga": Day 1 is Bhogi with early morning bonfire (Bhogi Mantalu) discarding old waste and showering children with Bhogi Pallu; Day 2 is Makara Sankranti offering newly harvested rice Pongal to Lord Surya amidst colorful muggulu (rangoli) with Gobbemmalu and songs of Haridasu; Day 3 is Kanuma worshipping cattle and agricultural livestock.',
            'content_te' => 'సూర్య భగవానుడు ధనుస్సు రాశి నుంచి మకర రాశిలోకి ప్రవేశించే పుణ్యకాలమే మకర సంక్రాంతి. తెలుగువారికి ఇది మూడు రోజుల పెద్ద పండుగ. మొదటి రోజు భోగి మంటలు, భోగి పళ్ళు; రెండవ రోజు మకర సంక్రాంతి గంగిరెద్దుల విన్యాసాలు, హరిదాసు కీర్తనలు, పిండివంటలు; మూడవ రోజు కనుమ పశువుల పూజ ఘనంగా జరుపుకుంటారు.',
            'content_hi' => 'सूर्य देव जब धनु राशि से मकर राशि में प्रवेश करते हैं तो मकर संक्रांति मनाई जाती है। यह उत्तरायण का पावन पर्व है। इस दिन गंगा स्नान, तिल-गुड़ के दान और खिचड़ी भोग का अनंत पुण्य प्राप्त होता है।',
            'significance' => 'Thanksgiving to the Sun God for harvest, fertility, cosmic energy, and discarding old negativity.',
            'history' => 'Bhishma Pitamaha chose Uttarayana Punya Kala to leave his mortal body on the battlefield of Kurukshetra.',
            'puja_timings' => 'Makara Sankranti Punya Kala Muhurat: 07:15 AM – 12:45 PM | Mahapunya Kala: 07:15 AM – 09:05 AM',
            'samagri' => 'New harvest raw rice, Jaggery, Cow milk, Sugarcane (Cheruku), Turmeric plants, Sesame seeds (Nuvvulu), Cow dung for Gobbemmalu',
