            'title_en' => 'Maha Shivaratri (Lingodbhava Kalam)',
            'title_te' => 'మహా శివరాత్రి (నిశీథ కాల లింగోద్భవ పూజ & జాగరణ)',
            'title_hi' => 'महाशिवरात्रि (निशीथ काल लिंगोद्भव पूजन)',
