            'excerpt' => 'The Great Night of Shiva commemorating the cosmic Lingodbhava and divine marriage of Shiva and Parvati with four-prahar abhishekam and night vigil.',
            'content_en' => 'Maha Shivaratri is the most sacred night of the year dedicated to Lord Shiva. Occurring on Magha Krishna Chaturdashi, it commemorates Lingodbhava — the midnight moment Lord Shiva revealed Himself as the pillar of infinite cosmic light (Jyotirlinga) to Brahma and Vishnu. Millions of devotees observe absolute waterless or fruit fast (Upavasa), perform continuous Rudrabhishekam across all four watches of the night (Char Prahar Puja), and maintain unbroken wakefulness (Jagaran) chanting Om Namah Shivaya.',
            'content_te' => 'మాఘ బహుళ చతుర్దశి నాడే మహా శివరాత్రి. అర్ధరాత్రి వేళ లింగోద్భవం సంభవించిన మహాపవిత్ర దినం. భక్తులు రోజంతా కఠోర ఉపవాసం ఉండి, నాలుగు యామాల (ప్రహార) పూజలలో శివలింగానికి పాలు, పెరుగు, తేనె, నెయ్యి, పంచదారలతో పంచామృతాభిషేకం మరియు బిల్వార్చన చేస్తారు. రాత్రంతా నిద్రపోకుండా శివనామస్మరణతో జాగరణ చేయడం వల్ల జన్మజన్మల పాపాలు తొలగి శివసాయుజ్యం లభిస్తుంది.',
            'content_hi' => 'महाशिवरात्रि पर भगवान शिव करोड़ों सूर्यों के तेज से युक्त ज्योतिर्लिंग रूप में प्रकट हुए थे। इस पावन रात्रि में चार प्रहर का अभिषेक, बेलपत्र अर्पण, उपवास और रात्रि जागरण करने से साधक के सभी पाप भस्म हो जाते हैं।',
            'significance' => 'Overcoming sensory delusions, mastery of the mind, and dissolution of individual ego into the infinite stillness of Shiva.',
            'history' => 'Cosmic manifestation of the endless pillar of fire (Lingodbhava); also celebrated as the celestial wedding night of Lord Shiva and Goddess Parvati.',
            'puja_timings' => 'Nishita Lingodbhava Muhurat: 11:55 PM – 12:45 AM | Char Prahar Puja: 06:15 PM, 09:30 PM, 12:45 AM, 03:45 AM',
            'samagri' => 'Shiva Lingam, Fresh Bilva leaves (three-leafed clusters), Pure cow milk, Curd, Honey, Cow ghee, Sugar, Sandalwood paste, Bhasma (Vibhuti), Dhatura flowers',
            'naivedyam' => 'Panchamritam, Fruits, Coconut water, Ksheerannam',
            'vrat_rules' => 'Strict fast from sunrise until next morning sunrise; continuous Japa and Jagaran through the night.',
            'dos' => 'Offer Bilva leaves reciting "Tridalam Trigunakaram", chant Maha Mrityunjaya and Sri Rudram, stay awake meditating throughout the night.',
            'donts' => 'Do not sleep during the night; do not offer Tulasi or Kumkum to Shiva Lingam; strictly avoid tamasic food.',
