            'excerpt' => 'Advent of Spring season and appearance day of Goddess Saraswati, celebrated with yellow attire and Aksharabhyasam.',
            'content_en' => 'Vasant Panchami (Sri Panchami) heralds the arrival of spring (Vasant Ritu) and marks the appearance day of Goddess Saraswati, the deity of learning, arts, music, and wisdom. Devotees and students wear bright yellow clothes, place books, pens, and musical instruments before the Goddess, and perform Saraswati Puja. In Telangana, Basara Sri Gnana Saraswati temple witnesses grand Aksharabhyasam (child\'s first writing ceremony) on this sacred day.',
            'content_te' => 'మాఘ శుద్ధ పంచమి నాడు చదువుల తల్లి సరస్వతీ దేవి జన్మదినాన్ని వసంత పంచమి లేదా శ్రీ పంచమిగా జరుపుకుంటారు. బాసర జ్ఞాన సరస్వతి క్షేత్రంలో వేలాది మంది చిన్నారులకు అక్షరాభ్యాసం చేయిస్తారు. పసుపు వస్త్రాలు ధరించి, పుస్తకాలు, పెన్నులు అమ్మవారి ముందు ఉంచి పూజ చేస్తారు.',
            'content_hi' => 'माघ शुक्ल पंचमी को ज्ञान, संगीत और कला की देवी मां सरस्वती का प्राकट्य हुआ था। इस दिन पीले वस्त्र धारण करने और विद्या आरंभ करने की परंपरा है।',
