            'excerpt' => 'Birthday of the Sun God when Surya turned his seven-horse chariot towards the northern hemisphere, celebrated with Jilledu leaf snana.',
            'content_en' => 'Ratha Saptami, also hailed as Surya Jayanti, marks the day Lord Surya illuminated the universe on His golden chariot driven by Aruna and drawn by seven horses (symbolizing the seven spectrum rays and days of the week). Devotees take early morning Arunodaya bath placing seven Calotropis (Jilledu / Arka) leaves with raw rice on seven bodily centers (head, shoulders, knees, feet) and boil cow milk in an earthen pot outdoors until it overflows towards the east.',
            'content_te' => 'మాఘ శుద్ధ సప్తమి నాడు సూర్య భగవానుని జన్మదినాన్ని రథసప్తమిగా జరుపుకుంటారు. వేకువజామున అరుణోదయ వేళలో ఏడు జిల్లేడు ఆకులపై (అర్క పత్రాలు) బియ్యం, రేగుపళ్ళు పెట్టుకుని తలపై, భుజాలపై ధరించి స్నానం చేస్తే సకల రోగాలు, పాపాలు నశిస్తాయి. ఆరుబయట పొయ్యి పెట్టి ఆవుపాలతో పరమాన్నం వండి సూర్య భగవానునికి నివేదిస్తారు. తిరుమలలో మలయప్ప స్వామివారి ఒకేరోజు సప్తవాహన సేవ జరుగుతుంది.',
            'content_hi' => 'माघ शुक्ल सप्तमी को सूर्य देव का रथ उत्तरायण की ओर मुड़ता है। इस दिन अरुणोदय काल में आक (मदार) के पत्तों को सिर पर रखकर स्नान करने से आरोग्य और कांति की प्राप्ति होती है।',
            'significance' => 'Vitality, optical wellness, longevity, and liberation from ancestral and physical illnesses.',
            'history' => 'Sage Kashyapa and Aditi gave birth to Martanda (Surya) on this day; Sage Agastya taught the Aditya Hridaya Stotra.',
