            'content_en' => 'Holi is celebrated over two days on Phalguna Purnima. The eve of Holi is observed as Holika Dahan (in South India commemorated as Kamadahana, when Lord Shiva burned the god of desire Kama Deva to ashes). The next morning is Dhulandi or Rangwali Holi, celebrated with organic colors, singing, and sweets, celebrating the transcendental love of Radha and Krishna and the deliverance of Bhakta Prahlada from fire.',
            'content_te' => 'ఫాల్గుణ పౌర్ణమి నాడు రంగుల పండుగ హోలీని జరుపుకుంటారు. ముందు రోజు రాత్రి కామదహనం (హోలికా దహనం) చేసి దుష్టశక్తులపై మంచి విజయాన్ని చాటుతారు. మరుసటి రోజు సహజసిద్ధమైన రంగులు, గులాల్ చల్లుకుంటూ ఆనందోత్సాహాలతో వసంతోత్సవాన్ని జరుపుకుంటారు.',
            'content_hi' => 'फाल्गुन पूर्णिमा को होलिका दहन और अगले दिन रंगों का महापर्व होली (धुलेंडी) मनाया जाता है। यह पर्व भक्त प्रह्लाद की रक्षा, कामदेव के भस्म होने और राधा-कृष्ण के दिव्य प्रेम का प्रतीक है।',
            'significance' => 'Destruction of ego and lust, triumph of virtue, and celebration of cosmic joy and brotherhood.',
            'history' => 'Holika perished in fire while trying to burn devotee Prahlada; Lord Shiva opened His third eye incinerating Kama Deva.',
