            'excerpt' => 'Nine-day glorious floral festival of Telangana where women arrange seasonal wildflowers in conical tiers to worship Mother Gauri.',
            'content_en' => 'Bathukamma is the signature cultural festival of Telangana celebrating feminine divinity and nature. The word Bathukamma means "Come alive, Mother Goddess". Commencing on Mahalaya Amavasya (Engili Pula Bathukamma) and concluding on Durgashtami (Saddula Bathukamma), women arrange seasonal medicinal wildflowers (Gunugu, Thangedu, Gummadi, Katla) in concentric conical tiers on brass plates, placing a turmeric Gouramma on top. In the evening, women sing melodious folk songs clapping in rhythm around Bathukamma, before immersing the flowers into local ponds.',
            'content_te' => 'తెలంగాణ సంస్కృతికి తలమానికమైన పండుగ బతుకమ్మ. తీరొక్క పూలతో శంఖాకారంలో బతుకమ్మలను పేర్చి గౌరమ్మను ప్రతిష్టించి మహిళలంతా ఒకచోట చేరి పాటలు పాడుతూ ఆనందంగా ఆడుకుంటారు. ఎంగిలిపూల బతుకమ్మతో మొదలై సద్దుల బతుకమ్మతో తొమ్మిది రోజుల పండుగ ముగుస్తుంది. సద్దుల బతుకమ్మ నాడు పెరుగన్నం, పులిహోర, నువ్వుల పొడి సద్దులను సమర్పించి చెరువులలో బతుకమ్మను నిమజ్జనం చేస్తారు.',
            'content_hi' => 'बथुकम्मा तेलंगाना का प्रसिद्ध पुष्प उत्सव है जो नवरात्रि के दौरान नौ दिनों तक मनाया जाता है। महिलाएं रंग-बिरंगे मौसमी फूलों से सुंदर आकृतियां बनाती हैं और देवी गौरी की आराधना करती हैं।',
            'significance' => 'Environmental protection, veneration of wildflowers with medicinal values, and empowerment of womanhood.',
