            'excerpt' => 'Telugu women\'s traditional festival celebrated with early morning Suda, swing rides, Gauri puja, and offering 10 mini dosas (Atlu).',
            'content_en' => 'Atla Tadde is the Telugu counterpart of Karwa Chauth celebrated on the third day of Ashwina Krishna Paksha. Unmarried girls observe it to be blessed with an ideal husband, while married women observe it for their husband\'s longevity. The day starts before dawn with Suda (eating cold rice cooked the previous night with Gongura chutney). Throughout the day, women swing on tree swings (Uyyala), apply Mehendi (Gorintaku), and after sighting the moon at night, worship Goddess Gauri and offer 10 tiny dosas (Atlu) as Vayanam.',
            'content_te' => 'ఆశ్వయుజ బహుళ తదియ నాడు తెలుగు ఆడపడుచులు అట్ల తద్దెను ఘనంగా జరుపుకుంటారు. వేకువజామునే చద్ది అన్నం, గోంగూర పచ్చడి తినడం (సుద్ద తినడం), రోజంతా ఉపవాసం ఉండి గోరింటాకు పెట్టుకుని ఉయ్యాలలు ఊగడం ఆచారం. రాత్రి చంద్రుని చూసిన తర్వాత గౌరీదేవికి పూజ చేసి 10 అట్లను వాయనంగా ముత్తైదువులకు సమర్పిస్తారు.',
            'content_hi' => 'अट्ला तद्दे आंध्र प्रदेश और तेलंगाना में महिलाओं द्वारा मनाया जाने वाला करवा चौथ सदृश व्रत है। इस दिन महिलाएं अखंड सौभाग्य और कुंवारी कन्याएं योग्य वर प्राप्ति हेतु व्रत रखती हैं और देवी गौरी को 10 दोसे (अट्लु) अर्पित करती हैं।',
            'significance' => 'Marital longevity, harmony, joy of sisterhood, and cultural bonding through swings and mehendi.',
            'history' => 'Goddess Parvati observed this vrata under Sage Narada\'s guidance to win Lord Shiva as Her husband.',
            'puja_timings' => 'Morning Suda: 04:00 AM – 05:15 AM | Evening Moonrise Gauri Puja: 07:30 PM – 09:15 PM',
            'samagri' => 'Mehendi (Gorintaku), Dosa batter (rice and black gram), Gauri idol, 10 Betel leaves, Yellow thread, Turmeric',
