            'excerpt' => 'Nirjala fasting observed by married women for their husband\'s longevity and happiness, broken after sighting the moon through a sieve.',
            'content_en' => 'Karwa Chauth is an austere fasting ritual observed by married women in North and Western India on Kartika Krishna Chaturthi. Women observe a rigorous waterless fast (Nirjala Upavasa) from sunrise to moonrise for the health, safety, and longevity of their husbands. In the evening, women gather to recite the Karwa Chauth katha and rotate thalis. Once the moon rises, women sight the moon through a sieve (Chhalni), then look upon their husband, offer Arghya to the moon, and drink water from their husband\'s hands.',
            'content_te' => 'కార్తీక కృష్ణ చతుర్థి నాడు ఉత్తర భారతదేశంలో మహిళలు కరవా చౌత్ వ్రతాన్ని ఆచరిస్తారు. రోజంతా చుక్క నీరు కూడా ముట్టకుండా నిర్జల ఉపవాసం ఉంటారు. రాత్రి చంద్రోదయం తర్వాత జల్లెడ ద్వారా చంద్రుడిని, ఆపై భర్తను చూసి భర్త చేతుల మీదుగా నీరు తాగి ఉపవాసాన్ని విరమిస్తారు.',
            'content_hi' => 'कार्तिक कृष्ण चतुर्थी को सुहागिन महिलाएं अपने पति की दीर्घायु और अखंड सौभाग्य के लिए निर्जला व्रत रखती हैं। शाम को कथा सुनकर छलनी से चांद और पति का दीदार कर अर्घ्य दिया जाता है।',
            'significance' => 'Marital devotion, unshakeable fidelity, and spiritual prayer for husband\'s life and welfare.',
