            'excerpt' => 'First day of Diwali festivities honoring Lord Dhanvantari, the god of Ayurveda, and purchasing metals and gold for prosperity.',
            'content_en' => 'Dhanteras (Dhantrayodashi) kicks off the five-day Diwali celebrations on Ashwina Krishna Trayodashi. It commemorates the appearance of Lord Dhanvantari, the divine physician and avatar of Vishnu, who emerged from the churned ocean carrying the vessel of cosmic nectar (Amrita Kalash). People purchase gold, silver, brass utensils, and Lakshmi-Ganesha idols. In the evening, Yamadeepdaan (lighting a four-wick lamp facing South) is performed to ward off premature death (Apamrityu).',
            'content_te' => 'దీపావళి పండుగకు నాందిగా ఆశ్వయుజ బహుళ త్రయోదశి నాడు ధన త్రయోదశిని జరుపుకుంటారు. క్షీరసాగర మథనంలో అమృత కలశంతో ధన్వంతరి భగవానుడు జన్మించిన రోజు ఇది. బంగారం, వెండి, ఇత్తడి వస్తువులు కొనుగోలు చేయడం శుభప్రదం. అకాల మృత్యు నివారణ కోసం యమదీపం వెలిగిస్తారు.',
            'content_hi' => 'कार्तिक कृष्ण त्रयोदशी को धनतेरस मनाया जाता है। इसी दिन समुद्र मंथन से आयुर्वेद के जनक भगवान धन्वंतरि अमृत कलश लेकर प्रकट हुए थे। इस दिन सोना, चांदी व बर्तन खरीदना शुभ माना जाता है और यमराज के लिए दीपदान किया जाता है।',
            'significance' => 'Good health through Ayurveda, economic prosperity, and protection against premature demise.',
            'history' => 'Emergence of Dhanvantari with Amrita; King Hima\'s 16-year-old son was saved from Yama\'s death serpent by blinding heaps of gold jewelry.',
            'puja_timings' => 'Dhanvantari & Kubera Puja: 06:50 PM – 08:25 PM | Metal Purchase: Full Day',
            'samagri' => 'Four-wick earthen lamp (Choumukha diya), Sesame oil, Brass utensil or gold/silver coin, Coriander seeds (Dhaniya)',
            'naivedyam' => 'Panchamritam, Kheer, Whole coriander seeds mixed with jaggery, Seasonal fruits',
            'vrat_rules' => 'Light Yamadeepam facing South outside the house entrance at dusk.',
            'dos' => 'Buy brass utensils or gold, light Yamadeepdaan facing South, worship Dhanvantari for health.',
            'donts' => 'Do not purchase sharp iron items, glass, or black objects on Dhanteras.',
