            'content_te' => 'ఆశ్వయుజ బహుళ చతుర్దశి నాడు సత్యభామా సమేత శ్రీకృష్ణుడు నరకాసురుని వధించి లోకానికి పీడ విరగడ చేశారు. తెలుగునాట ఈ రోజే దీపావళి సంబరాలు ఘనంగా మొదలవుతాయి. వేకువజామునే నువ్వుల నూనెతో తలంటు స్నానం చేసి, నూతన వస్త్రాలు ధరించి, బాణసంచా కాలుస్తారు.',
            'content_hi' => 'नरक चतुर्दशी को छोटी दिवाली और रूप चौदस भी कहा जाता है। इस दिन भगवान श्रीकृष्ण और सत्यभामा ने नरकासुर का वध किया था। सूर्योदय से पूर्व तैल स्नान करने से नरक के भय से मुक्ति मिलती है।',
