            'content_en' => 'Govardhan Puja (Annakut) is celebrated on the day following Diwali on Kartika Shukla Pratipada. Lord Sri Krishna lifted the sacred Govardhan Hill on His left pinky finger for seven continuous days to protect the cowherds, milkmaids, and cattle of Vrindavan from the torrential wrath of Indra. Devotees fashion replica mounds of Govardhan hill from cow dung, worship cows (Go Puja), and offer 56 varieties of vegetarian delicacies (Chhappan Bhog / Annakut).',
            'content_te' => 'కార్తీక శుద్ధ పాడ్యమి నాడు గోవర్ధన పూజ మరియు అన్నకూట్ పండుగ జరుపుకుంటారు. ఇంద్రుని గర్వాన్ని అణచి బ్రజవాసులను రక్షించడానికి శ్రీకృష్ణుడు గోవర్ధన గిరిని చిటికెన వేలిపై ఎత్తిన పుణ్యదినం. ఆవుపేడతో గోవర్ధన పర్వతాన్ని చేసి పూజించి, గోపూజ చేసి, 56 రకాల వంటకాలను (అన్నకూట్) స్వామివారికి నివేదిస్తారు.',
            'content_hi' => 'कार्तिक शुक्ल प्रतिपदा को गोवर्धन पूजा और अन्नकूट उत्सव मनाया जाता है। श्रीकृष्ण ने इंद्र के अभिमान को चूर कर ब्रजवासियों की रक्षा हेतु गोवर्धन पर्वत को उंगली पर उठाया था। इस दिन गायों की पूजा और 56 भोग का विधान है।',
