            'content_en' => 'Bhai Dooj (Yama Dwitiya / Bhagini Hasta Bhojanam) concludes the five-day Diwali festival on Kartika Shukla Dwitiya. Lord Yamaraj visited His sister Yamuna on this day, relished the feast she prepared, and granted a boon that any brother who receives tilak and eats food prepared with affection by his sister on this day shall never suffer an untimely demise.',
            'content_te' => 'కార్తీక శుద్ధ విదియ నాడే యమ ద్వితీయ లేదా భగినీ హస్తభోజనం. యమధర్మరాజు తన సోదరి యమున ఇంటికి వెళ్లి ఆమె చేతి వంట ఆరగించిన పవిత్ర దినం. సోదరులు తమ అక్కాచెల్లెళ్ల ఇంటికి వెళ్లి భోజనం చేసి, వారికి కానుకలు ఇచ్చి ఆశీర్వాదం తీసుకోవడం వల్ల అపమృత్యు భయాలు తొలగుతాయి.',
            'content_hi' => 'कार्तिक शुक्ल द्वितीया को भाई दूज या यम द्वितीया मनाई जाती है। यमराज ने अपनी बहन यमुना के घर जाकर भोजन ग्रहण किया था और वरदान दिया था कि जो भाई इस दिन बहन के हाथ का भोजन करेगा, उसे अकाल मृत्यु का भय नहीं रहेगा।',
