            'excerpt' => 'The holiest month in the Hindu calendar dedicated to daily morning river baths, deeparadhana, Somavara fasting, and Vanabhojanam.',
            'content_en' => 'Karthika Masam is regarded in the Skanda Purana as the supreme month without peer ("Na Kartika Samo Maso"). Throughout this month, devotees rise during Brahma Muhurtham to take early morning cold baths (Nadi Snana), light clay ghee lamps at temples and before the Tulasi plant, observe Karthika Somavara (Monday) fasting, read the 30 chapters of Karthika Purana daily, and partake in community feasts under Amla trees (Vanabhojanam).',
            'content_te' => 'మాసాలలో కార్తీక మాసానికి సాటియైనది లేదని స్కాంద పురాణం చెబుతోంది. హరిహరుల ఆరాధనకు అత్యంత ప్రశస్తమైన ఈ మాసంలో రోజూ తెల్లవారుజామునే చన్నీటి స్నానం చేయడం, తులసి కోట వద్ద దీపారాధన చేయడం, కార్తీక సోమవారాల్లో ఉపవాసం ఉండడం విశేష పుణ్యాన్ని ఇస్తాయి. ఉసిరి చెట్ల నీడన వనభోజనాలు చేయడం ఆనవాయితీ.',
            'content_hi' => 'कार्तिक मास को शास्त्रों में सर्वोत्तम मास कहा गया है। इस पूरे महीने सूर्योदय से पूर्व स्नान, आकाशदीप दान, तुलसी पूजन और शिव-विष्णु आराधना से अश्वमेध यज्ञ के समान पुण्य प्राप्त होता है।',
            'significance' => 'Attainment of Shiva Sayujya and Vaikuntha loka, purification of soul, and universal harmony.',
            'history' => 'Detailed across 30 chapters of the Karthika Purana in the Skanda and Padma Puranas.',
