            'content_en' => 'Vaikuntha Ekadashi (known as Mukkoti Ekadashi in Telugu states) is observed during Dhanurmasam on Margashirsha Shukla Ekadashi. Tradition holds that the gates of Vaikuntha (Vaikuntha Dvaram / Uttara Dvaram) are thrown wide open on this day. Passing through the northern gate of Lord Venkateswara at Tirumala or any Vaishnava temple after observing strict fasting leads to liberation (Moksha). It also marks Gita Jayanti, the day Lord Krishna delivered the Bhagavad Gita to Arjuna on the battlefield of Kurukshetra.',
            'content_te' => 'ధనుర్మాసంలో వచ్చే మార్గశిర శుద్ధ ఏకాదశినే ముక్కోటి ఏకాదశి లేదా వైకుంఠ ఏకాదశి అంటారు. ఈ రోజున వైకుంఠ ద్వారాలు తెరుచుకుంటాయి. తిరుమల శ్రీవారి ఆలయంలో మరియు అన్ని విష్ణు దేవాలయాలలో ఉత్తర ద్వార దర్శనం చేసుకుంటే ముక్కోటి దేవతల అనుగ్రహం మరియు మోక్షం లభిస్తుంది. ఇదే రోజున గీతా జయంతి కూడా జరుపుకుంటారు.',
            'content_hi' => 'मार्गशीर्ष शुक्ल एकादशी को वैकुंठ एकादशी और मोक्षदा एकादशी कहा जाता है। इस दिन वैकुंठ के द्वार खुलते हैं। मंदिरों में उत्तर द्वार से दर्शन करने और गीता पाठ करने से मोक्ष की प्राप्ति होती है।',
            'significance' => 'Attainment of Vaikuntha abode, eradication of birth-death cycle, and honoring the Bhagavad Gita.',
            'history' => 'Lord Vishnu opened the northern gateway of Vaikuntha for two demons Madhu and Kaitabha, granting salvation.',
