            'content_en' => 'Datta Jayanti celebrates the birth of Lord Dattatreya to Sage Atri and Mata Anasuya on Margashirsha Purnima. Lord Dattatreya is revered as the Adi Guru of the universe, embodying the combined powers of Brahma (creation), Vishnu (sustenance), and Shiva (dissolution), accompanied by four dogs symbolizing the four Vedas and a cow representing Mother Earth. Devotees recite the Guru Charitra and chant "Digambara Digambara Sripada Vallabha Digambara".',
            'content_te' => 'మార్గశిర పౌర్ణమి నాడు అత్రి మహర్షి, అనసూయ దేవిల పుత్రుడైన దత్తాత్రేయ స్వామి జన్మించారు. బ్రహ్మ, విష్ణు, మహేశ్వరుల త్రిమూర్తి స్వరూపమే దత్తాత్రేయుడు. గురుపీఠాలకు మూలపురుషుడైన దత్తాత్రేయుని ఆరాధించడం వల్ల అజ్ఞానం తొలగి, మోక్ష మార్గం లభిస్తుంది. గురు చరిత్ర పారాయణ చేయడం విశేషం.',
            'content_hi' => 'मार्गशीर्ष पूर्णिमा को त्रिदेव (ब्रह्मा, विष्णु, महेश) के संयुक्त अवतार भगवान दत्तात्रेय का प्राकट्य हुआ था। वे योग और ज्ञान के आदि गुरु हैं। इस दिन गुरु चरित्र का पाठ अत्यंत कल्याणकारी माना जाता है।',
