            'excerpt' => 'First day of Sankranti celebrated with early dawn bonfires, discarding old discarded items, and showering toddlers with Bhogi Pallu.',
            'content_en' => 'Bhogi is the inaugural day of the four-day Makara Sankranti festivities. Before sunrise, families light the traditional Bhogi Mantalu (bonfire) fueled with dried cow dung cakes and discarded agricultural scrap, symbolizing the burning away of old vices and welcoming divine illumination. In the evening, women shower small children with "Bhogi Pallu" (a blessing mixture of Indian jujube fruit, sugarcane pieces, raw rice, and flower petals) to protect them from the evil eye (Drishti).',
            'content_te' => 'సంక్రాంతి పండుగలో మొదటి రోజు భోగి. వేకువజామునే చలిని తరిమేస్తూ పాత వస్తువులు, పిడకలతో భోగి మంటలు వేస్తారు. చెడును వదిలేసి మంచిని ఆహ్వానించే సంకేతం ఇది. సాయంత్రం వేళ ఐదేళ్ల లోపు చిన్నారులకు దిష్టి తగలకుండా రేగుపళ్ళు, నాణాలు, చిల్లర, చెరుకుగడలు కలిపిన "భోగి పళ్ళు" తలపై పోసి ఆశీర్వదిస్తారు.',
            'content_hi' => 'भोगी मकर संक्रांति से एक दिन पूर्व मनाया जाने वाला दक्षिण भारतीय पर्व है। प्रातःकाल पुरानी वस्तुओं और उपलों की पवित्र अग्नि जलाई जाती है और बच्चों को बुरी नजर से बचाने हेतु भोगी पल्लु की रस्म निभाई जाती है।',
