            'excerpt' => 'Third and fourth days of Sankranti worshipping cows, bulls, and livestock who toil throughout the year for human nourishment.',
            'content_en' => 'Kanuma is celebrated on the day after Makara Sankranti in Andhra Pradesh and Telangana. It is dedicated to expressing immense gratitude to cattle, oxen, and agricultural tools that partner with farmers throughout the year. Bulls and cows are washed, their horns painted in bright hues with brass caps, adorned with flower garlands, and fed sweet Pongal. Tradition holds that travel should be avoided on Kanuma ("Kanuma roju kaaki kooda bayatiki velladu"). The following day is celebrated as Mukkanuma with family gatherings.',
            'content_te' => 'సంక్రాంతి మరుసటి రోజే కనుమ పండుగ. దీనిని పశువుల పండుగ అంటారు. రైతులకు పంటలు పండించడంలో చేదోడువాదోడుగా నిలిచే ఎద్దులు, ఆవులను కడిగి, కొమ్ములకు రంగులు వేసి, పూలమాలలు వేసి పూజిస్తారు. "కనుమ నాడు కాకి కూడా కదలదు" అని ప్రయాణాలు మానుకుంటారు. ఆ తర్వాతి రోజు ముక్కనుమగా బంధుమిత్రులతో కలిసి విందులు చేసుకుంటారు.',
            'content_hi' => 'कनुमा मकर संक्रांति के अगले दिन मनाया जाने वाला पशुधन आभार उत्सव है। किसान अपने बैलों और गायों को सजाकर उनकी पूजा करते हैं। इस दिन यात्रा करना वर्जित माना जाता है।',
